    TrackLink_: function (el) {
        if (el && el.href && el.href.indexOf("trackingId") < 0) {
            el.href += (el.href.indexOf("?") < 0 ? "?" : "&") + "trackingId=" + window.trackingId;
            el.addEventListener("click", function (e) {
                var name = "", campain = "";
                var $el = $(this);
                name = typeof $el.data("name") !== "undefined" ? $el.data("name") : (typeof $el.data("nome") !== "undefined" ? $el.data("nome") : $el[0].className);
                campain = $el.data("campanha");
                campain = typeof campain != "undefined" ? campain : "none";
                if (Publico.fullClean) {
                    campain += "_flagged";
                }

                var data = {
                    init: name,
                    exp: campain,
                    trackingId: window.trackingId,
                    url: document.location.href,
                    userId: window.userId
                };
                Publico.Cookies.save("_conv", JSON.stringify(data));
                if (document.body.classList.contains("is-paywalled")) {
                    //Publico.Track.Event("PAYWALL", "click", name + (campain != "" && campain.length > 1 ? "_" + campain : ""));
                } else {
                    Publico.Track.Event("Subscribe", "click", name + (campain != "" && campain.length > 1 ? "_" + campain : ""));
                }
                Publico.PingLog(data);
            });
        }
    },
