    Utils: {
        IsDarkMode: window.matchMedia("(prefers-color-scheme: dark)").matches,
        IsMobile: window.matchMedia("only screen and (max-width: 767px)").matches,
        GetUrlParam: function (name) {
            name = name.replace(/[\[]/, "\\[").replace(/[\]]/, "\\]");
            var regex = new RegExp("[\\?&]" + name + "=([^&#]*)"), results = regex.exec(location.search);
            return results === null ? "" : decodeURIComponent(results[1].replace(/\+/g, " "));
        },
        DOMParser: function () {
            if (typeof window.domParser == "undefined") {
                window.domParser = new DOMParser();
            }
            return window.domParser;
        },
        GetScript: function (source) {
            return new Promise(function (resolve, reject) {
                var script = document.createElement("script");
                script.async = true;
                script.defer = true;
                script.onload = function () {
                    resolve();
                };
                script.onerror = function () {
                    reject();
                };
                script.src = source;

                var elPos = document.getElementsByTagName('script')[0];
                elPos.parentNode.insertBefore(script, elPos);

            });
        },
        ExecuteInlineScript: function (el) {
            return new Promise(function (resolve, reject) {
                var arr = Array.from(el.querySelectorAll("script"));
                arr.forEach(function (oldScript, i) {
                    var newScript = document.createElement("script");
                    Array.from(oldScript.attributes).forEach(function (attr) {
                        newScript.setAttribute(attr.name, attr.value)
                    });
                    newScript.appendChild(document.createTextNode(oldScript.innerHTML));
                    oldScript.parentNode.replaceChild(newScript, oldScript);
                    if (i == arr.length - 1) {
                        resolve();
                    }
                });
            });
        },
        Template: function (name, folder, data) {
            return new Promise(function (resolve, reject) {
                var el = document.getElementById(name);
                if (el == null) {
                    if (typeof folder !== "undefined" && folder !== "" && folder.substr(folder.length - 1) !== "/") folder += "/";
                    var request = $.ajax("/templates/" + folder + name + ".html?v" + Publico.cbJS);
                    request.then(function (html) {
                        var script = document.createElement('script');
                        script.id = name;
                        script.type = "x-tmpl-mustache";
                        script.innerHTML = html;
                        document.getElementsByTagName('head')[0].appendChild(script);
                        if (data) {
                            var compiled = Handlebars.compile(html);
                            resolve(compiled(data));
                        } else {
                            resolve(html);
                        }
                    }).fail(function (error, satus, code) {
                        reject(error);
                    });
                } else {
                    if (data) {
                        var html = el.innerHTML;
                        var compiled = Handlebars.compile(html);
                        resolve(compiled(data));
                    } else {
                        resolve(el.innerHTML);
                    }
                }
            });
        },
        Waypoint: function (el, cbIn, cbOut, ic) {
            var $this = el;
            var ic = typeof ic == "undefined" ? false : true;
            return new Waypoint.Inview({
                element: $this,
                enter: function (direction) {
                    if (!ic) {
                        cbIn($this);
                        this.destroy();
                    }
                },
                entered: function (direction) {
                    if (ic) {
                        cbIn($this);
                    }
                },
                exit: function (direction) {
                    if (typeof cbOut == "function") {
                        cbOut($this);
                    }
                },
                exited: function (direction) {
                    if (typeof cbOut == "function") {
                        cbOut($this);
                    }
                }
            });
        },
        CanShowMessage: function () {
            var el = document.querySelector(".site-message") || document.querySelector(".update-alert");
            if (el != null) {
                var dp = window.getComputedStyle(el);
                if (el.classList.contains("hidden") || (!el.classList.contains("show") && dp.display == "block") || dp.display == "none") {
                    return true;
                }
                return false;
            }
            return true;
        }
    },
