function getInContentContainer(el) {
        var newDiv = document.createElement("aside");
        newDiv.classList.add("ad-slot");
        newDiv.classList.add("ad-slot--in-content");
        //newDiv.classList.add("story__callout--ad-in-content");

        var adSlot = document.createElement("div");
        //adSlot.classList.add("pubVert");
        adSlot.classList.add("inContent");

        newDiv.appendChild(adSlot);
        el.replaceWith(newDiv);
    }

function buildContainer(el, extra) {
        //console.log("ADS: " + extra);
        var aside = document.createElement("aside");
        aside.classList.add("ad-slot");
        aside.classList.add("ad-slot--sticky");
        var wrapper = document.createElement("div")
        wrapper.classList.add("ad-slot--sticky-wrapper")

        var pub = document.createElement("div");
        pub.classList.add("pubVert");
        pub.classList.add("pubtxt");
        pub.id = el.id;
        pub.dataset = el.dataset;
        if (extra) pub.classList.add(extra);

        wrapper.appendChild(pub);
        aside.appendChild(wrapper);
        aside.dataset = el.dataset;
        el.replaceWith(aside);
    }

