            var verSize = googletag
                .sizeMapping()
                .addSize([0, 0], [[300, 250], [300, 200], [300, 600], [300, 130], [300, 60], [200, 200], [250, 250], [320, 160], [320, 50], [320, 100], [300, 50], [300, 100], [300, 75], [234, 60], [180, 150], [125, 125], "fluid"])
