document.addEventListener("page.homepage", function (data) {
    if (data && data.detail) {
        var el = data.detail;
        var size = el.dataset.size || 20;
        var skip = el.dataset.skip || 0;
        var isOp = el.dataset.op || false;
        var evLabel = el.dataset.label || "n/a";
        var dataUrl = el.dataset.url;
        var dataTemplate = el.dataset.template;
        var documentId = window.publicoConfig.pageArticleId;
        dataUrl += dataUrl.indexOf("?") < 0 ? "?" : "";
        size = parseInt(size);
        //

        var fetchContent = function (el) {
            fetch(dataUrl + "&op=" + isOp + "&size=" + (size + 1) + "&skip=" + skip).then(function (result) {
                result.json().then(function (data) {
                    data = data.filter(function (d) { return d.id != documentId });
                    if (data.length > size) { data = data.slice(0, size); }
                    Publico.Track.Event("CAIXA", "view", evLabel);
                    try {
                        Publico.Utils.Template(dataTemplate, null, data).then(function (html) {
                            if (html != "") {
                                if (el.childElementCount > 1) {
                                    var $child = $(el.children[el.childElementCount - 1]);
                                    $child.before(html);
                                } else {
                                    el.innerHTML = el.innerHTML + html;
                                }
                                el.querySelectorAll(".teaser__text h3 a").forEach(function (a) {
                                    a.addEventListener("click", function (e) {
                                        Publico.Track.Event("CAIXA", "click", evLabel);
                                    });
                                });
                            }
                        });
                    } catch (e) {
                        console.log("error: " + e);
                    }
                });
            });
        }
        var ft = new fetchContent(el);
    }
});

