var getCaixaNewsletter = function (content) {
    if (typeof content != "undefined" && content != null) {
        showNewsletter(content);
    } else {
        var results = window.publicoConfig.pageSlugs.filter(function (e) { return window.publicoConfig.newsletterSections.indexOf(e) != -1; });

        if (results.length > 0 && !Publico.PauseSplitTraffic) {
            fetch("/api/traffic/split/6040", {
                method: "POST"
            }).then(function (result) {
                result.json().then(function (data) {
                    data && data.result == "0" ? showNewsletter(results[0]) : getSplitNewsletter();
                });
            }).catch(function (e) {
                getSplitNewsletter();
            });
        } else {
            getSplitNewsletter();
        }
    }
}

function getSplitNewsletter() {
    if (!Publico.PauseSplitTraffic) {
        fetch("/api/traffic/newsletter", {
            method: "POST"
        }).then(function (result) {
            result.json().then(function (data) {
                showNewsletter(data ? data.result : "A");
            });
        }).catch(function () {
            showNewsletter("A");
        });
    } else {
        showNewsletter("A");
    }
}

function showNewsletter(name) {
    var e = null;
    if (typeof name == "object") {
        e = {
            name: name.name,
            schedule: name.entry,
            token: name.legacyName,
            description: name.description,
            isForRegistered: name.isForRegistered
        };
    }
    else {
        if (typeof pageSlugs != "undefined" && Array.isArray(pageSlugs)) {
            pageSlugs.forEach(tag => {
                if (e != null) return;
                if (Publico.Newsletters[tag] != undefined)
                    e = Publico.Newsletters[tag];
            });
        }
        if (e == null)
            e = Publico.Newsletters[name];
    }

    if (typeof pageTags != "undefined" && pageTags.indexOf("Newsletters") > -1) {
        e = null;
    }

    if (e != null) {
        e.pos = "bottom";// userOnPage.segment == "0" ? "top" : "bottom";
        var elementConfig = e;
        var elementTitle = 'Subscreva a nossa newsletter';
        var elementModifier = 'newsletter-subscription--anonymous';
        var newsletterDisclaimer = "";
        if (e.isForRegistered && (typeof userOnPage != 'object' || !userOnPage.userGuid)) {
            newsletterDisclaimer = "";
        } else {
            newsletterDisclaimer = '<div class="input-group"><input id="form-newsletter-mrkt-ads" type="checkbox" required><label for="form-newsletter-mrkt-ads"><strong>Tomei conhecimento que as newsletter editoriais poderão conter publicidade.</strong> <span class="help-text help-text--required">Obrigatório</span></label></div> <div class="input-group"><input id="form-newsletter-mrkt" name="MARKETING" value="MARKETING" type="checkbox"><label for="form-newsletter-mrkt">Receba informações sobre ofertas, passatempos, campanhas especiais e eventos exclusivos do Público. <span data-tooltip aria-haspopup="true" class="has-tip" tabindex="1" data-show-on="small" data-allow-html="true" data-position-class="left" data-template-classes="tooltip--xl" title="Os dados pessoais recolhidos serão processados automaticamente pelo Público – Comunicação Social, S.A. na qualidade de responsável pelo tratamento dos dados, e destinam-se ao processamento do seu pedido e à prestação do serviço. Os dados serão ainda tratados para efeitos de marketing directo e acções de marketing do Público. <br><br>Nos termos da Lei n.º 67/98, de 26 de Outubro, é garantido o direito de acesso aos seus dados, podendo solicitar ao Público, por escrito, a sua actualização, correcção ou eliminação, através do email politicaprivacidade@publico.pt ou por correio para Jornal Público, Edifício Diogo Cão, Doca de Alcântara Norte, 1350-352 Lisboa.">Saber mais</span></label></div>';
        }

        if (typeof userOnPage == 'object' && userOnPage.userGuid) {
            elementModifier = 'newsletter-subscription--logged';
            newsletterDisclaimer = '<div class="input-group"><input id="form-newsletter-mrkt-ads" type="checkbox" required><label for="form-newsletter-mrkt-ads"><strong>Tomei conhecimento que as newsletter editoriais poderão conter publicidade.</strong> <span class="help-text help-text--required">Obrigatório</span></label></div>';
        }
        var newsletterHeader = '<h4 class="newsletter-subscription__title">' + elementTitle + ' ' + elementConfig.name + '</h4><h5 class="kicker">' + elementConfig.schedule + '</h5><p class="newsletter-subscription__description">' + elementConfig.description + '</p>';
        var newsletterFooter = '<div data-abide-error class="alert callout" style="display: none;"><p>Tem de preencher todos os campos obrigatórios.</p></div><div id="newsletter-form-error" class="alert callout" style="display: none;"><p>Ocorreu um erro. Por favor volte a tentar.</p></div><div id="newsletter-form-success" class="success callout" style="display: none;"><p>Subscreveu a newsletter ' + elementConfig.name + '. <a href="/newsletters">Veja as outras newsletters que temos para si</a>.</p></div><input type="hidden" id="newsletter-article-token" value="' + elementConfig.token + '">';
        var bottomElementInputs = '<div class="input-group"><input class="input-group-field" placeholder="Email" type="email" required id="newsletter-article-email"><div class="input-group-button"><input type="submit" class="button" value="Subscrever"></div></div>';
        if (typeof userOnPage == 'object' && userOnPage.userGuid) {
            bottomElementInputs = '<div class="input-group input-group-spaced"><input type="submit" class="button" value="Subscrever"></div>';
        } else if (e.isForRegistered) {
            Publico.Track.Event("CAIXA", 'view', "newsletter_registados");
            bottomElementInputs = '<div class="input-group input-group-spaced"><input onclick="document.location = \'/newsletters\';Publico.Track.Event(\'CAIXA\', \'click\', \'newsletter_registados\');" type="button" class="button" value="Subscreva aqui"></div>';
        }

        var bottomElementHtml = '<aside class="newsletter-subscription ' + elementModifier + '" id="newsletter-subscription"><div class="newsletter-subscription__content">' + newsletterHeader + '<form class="newsletter-subscription__form" novalidate data-abide id="newsletter-article-subscription">' + bottomElementInputs + '' + newsletterDisclaimer + '' + newsletterFooter + '</form></div></aside>';

        $("#extraContent").replaceWith(bottomElementHtml);

        Publico.Track.Event("CAIXA", 'view', "newsletter_" + Publico.CaixaColor, Publico.CaixaColor);

        $('#newsletter-article-subscription')
            .foundation()
            .on("formvalid.zf.abide", function (ev, frm) {
                if (!userOnPage || !userOnPage.userGuid) {
                    window.registerSource = "NEWSLETTER_CX_DINAMICA";
                    showLogin().then(function () {
                        document.querySelectorAll(".user-login__title").forEach(function (el) {
                            el.innerText = "Newsletter resservada a registados";
                        });
                        document.querySelectorAll(".user-login__sub-title").forEach(function (el) {
                            el.innerText = "Inicie sessão para continuar";
                            el.style.textTransform = "none";
                        });
                    });
                    return;
                }

                $('#newsletter-article-subscription').addClass('is-loading');

                Publico.Track.Event("CAIXA", 'click', "newsletter_" + Publico.CaixaColor, Publico.CaixaColor);

                var formData = { token: $('#newsletter-article-token').val(), marketing: $("#form-newsletter-mrkt").prop("checked") ? 1 : 0 };
                if (typeof userOnPage == 'object' && userOnPage.userGuid) {
                    formData.userId = userOnPage.userGuid;
                } else {
                    formData.email = $('#newsletter-article-email').val();
                }
                $('#newsletter-form-error').hide();

                $.ajax({
                    type: "POST",
                    url: "/api/newsletter",
                    data: JSON.stringify(formData),
                    contentType: "application/json",
                    dataType: "json"
                }).then(function (response) {
                    if (response && response.status) {
                        if (response.needsOptIn) {
                            $('#newsletter-form-success').find('p').text('Verifique o seu email para terminar a subscrição.').end();
                        }
                        $('#newsletter-form-success').show();
                        $('#newsletter-article-subscription').find('.input-group, .input-group-hidden').hide();
                    } else {
                        $('#newsletter-form-error').show();
                    }
                    $('#newsletter-article-subscription').removeClass('is-loading');
                }).fail(function (e, a) {
                    $('#newsletter-article-subscription').removeClass('is-loading');
                    $('#newsletter-form-error').show();
                });
            })
            .on("submit", function (ev) {
                ev.preventDefault();
            });
    }
}

