function getMoreAB(val) {
    if (typeof val != "undefined" && val != "0" && val != "" && 1 == 2) {
        var aside = document.createElement("aside");
        aside.classList.add("story__supplemental-slot");
        //aside.classList.add("story__supplemental-slot--pull");
        aside.classList.add("show-for-large");

        var box = document.querySelector("#more-box").parentElement;
        aside.appendChild(box);
        //var bodyContent = document.querySelector("#story-body");
        var bodyContent = document.querySelector(".story__supplemental-slot--margin");
        if (bodyContent != null) {
            bodyContent.appendChild(aside);
        }
    } else {
        val = "0";
    }

    Publico.Track.Event("CAIXA", "view", "ler mais " + (val == "0" ? "A" : "B"));
    document.querySelectorAll("#more-box li a").forEach(function (el) {
        if (el.parentElement.parentElement.dataset && el.parentElement.parentElement.dataset.replaceId) {
            el = el.parentElement.parentElement;
            fetch("/api/content/news/" + el.dataset.replaceId).then(function (result) {
                if (result.status == 200) {
                    result.json().then(function (response) {
                        var d = response;
                        var imageUrl = d.isItemOpinion && d.autores[0].imagem != null ? d.autores[0].imagem.url : d.imagens.length > 0 ? d.imagens[0].url : "";
                        var html = '<li class="headline-list__item media-object' + (d.isItemOpinion && d.imagens.length == 0 ? ' headline-list__item--opinion' : '') + '">';
                        if (imageUrl != "") {
                            html += '<a href="' + d.fullUrl + '" class="media-object-section headline-list__thumb" style="max-width:83px;" ><div class="flex-media">' +
                                '<img class="lazy" src="data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==" data-src="' + imageUrl + '&w=320&act=resize"' +
                                'data-sizes="auto" data-srcset="' + imageUrl + '&w=2048&act=resize 2048w,' +
                                imageUrl + '&w=1800&act=resize 1800w,' +
                                imageUrl + '&w=1600&act=resize 1600w,' +
                                imageUrl + '&w=1400&act=resize 1400w,' +
                                imageUrl + '&w=1280&act=resize 1280w,' +
                                imageUrl + '&w=1024&act=resize 1024w,' +
                                imageUrl + '&w=768&act=resize 768w,' +
                                imageUrl + '&w=640&act=resize 640w,' +
                                imageUrl + '&w=320&act=resize 320w" />' +
                                '</div></a>';
                        }
                        html += '<div class="media-object-section"><a href="' + d.fullUrl + '">';
                        if (!d.isItemOpinion) {
                            html += '<h5 class="kicker">';
                            if (d.isClosed) {
                                html += "<span class=\"badge--exclusive-label\">Exclusivo</span>&nbsp;";
                            }
                            html += "<span>" + d.rubrica + '</span></h5>';
                        } else if (d.isClosed) {
                            html += '<h5 class="kicker">';
                            if (d.isClosed) {
                                html += "<span class=\"badge--exclusive-label\">Exclusivo</span>&nbsp;";
                            }
                            html += '</h5>';
                        }
                        html += '<h4 class="headline">';
                        if (d.isItemOpinion) {
                            html += '<i class="i-quote" arida-hidden="true"></i>';
                        }
                        if (d.isClosed) {
                            //html += "<span class=\"badge--exclusive\"><span class=\"show-for-sr\">Exclusivo para assinantes</span></span>&nbsp;";
                        }
                        html += d.titulo;
                        if (d.isItemOpinion && d.autores.length > 0) {
                            html += " – " + d.rubrica + " de " + d.autores[0].nome;
                        }
                        html += "</h4></a></div>";
                        html += '</li>';
                        var $el = $(el);
                        var $html = $(html);
                        $el.replaceWith($html);
                        $html.find("a").on("click", function () {
                            Publico.Track.Event("CAIXA", 'click', 'ler mais' + (val == "0" ? "A" : "B"));
                        });
                    });
                } else {
                    el.querySelector("div a").addEventListerner("click", function () {
                        Publico.Track.Event("CAIXA", 'click', 'ler mais' + (val == "0" ? "A" : "B"));
                    });
                }
            });
        } else {
            el.addEventListener("click", function () {
                Publico.Track.Event("CAIXA", "click", "ler mais " + (val == "0" ? "A" : "B"));
            })
        }
    });
}

function unlockArticle() {
    if (window.documentId) {
        document.querySelectorAll(".btnBlock2").forEach(function (el) {
            el.addEventListener("click", function () {
                Publico.Track.Event("PAYWALL", "click", "try unlock");
                fetch("/api/user/unlock/" + window.documentId, { method: "post" }).then(function (response) {
                    if (response.status == 200) {
                        response.json().then(function (data) {
                            if (data.access_token) {
                                Publico.Track.Event("PAYWALL", "click", "unlocked");
                                document.location = location.pathname + "?access_token=" + encodeURIComponent(data.access_token);
                            } else {
                                Publico.Track.Event("PAYWALL", "click", "unlock no permissions");
                                $(".paywall-block__content").prepend("<div class=\"callout callout--message error\"><p>Não tem permissão ou já ultrapassou o limite de artigos disponíveis por mês</p></div>");
                            }
                        });
                    }
                }).catch(function () {
                    Publico.Track.Event("PAYWALL", "click", "unlock error");
                    $(".paywall-block__content").prepend("<div class=\"callout callout--message error\"><p>Ocorreu um erro, tente de novo</p></div>");
                });
            });
        });
    }
}

if (document.querySelector("#more-box") != null) {
    var abValue = Publico.Cookies.get("more_ab");
    if (!Publico.PauseSplitTraffic) {
        if (abValue == null) {
            this.fetch("/api/traffic/split/more_ab", {
                method: "POST",
            }).then(function (result) {
                if (result.status == 200) {
                    result.json().then(function (val) {
                        Publico.Cookies.save("more_ab", val.result, 365);
                        getMoreAB(val.result);
                    });
                } else {
                    getMoreAB("0");
                }
            }).catch(function () {
                getMoreAB("0");
            });
        } else {
            getMoreAB(abValue);
        }
    } else {
        getMoreAB("0");
    }
}

