if (document.querySelectorAll("button.button--subscriptions.button--offer").length > 0) {
    document.addEventListener("user.entityReady", function () {
        if (!userOnPage.isSubscriber) return;

        var maxShares = publicoConfig.isPremium ? 12 : 6;
        var panel = document.querySelector('.offer-panel-wrapper:not(.is-inline-wrapper) #modal-exclusive-offer');
        var overlay = document.querySelector('.offer-panel-overlay');
        var lock = document.querySelector('.offer-panel-lock');
        var jsonld = JSON.parse(document.querySelector('script[type="application/ld+json"]').textContent);

        var shareIconSVG = '<svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 18 18" fill="none">'
            + '<path fill-rule="evenodd" clip-rule="evenodd" d="M16.125 4.5C16.125 5.94975 14.9497 7.125 13.5 7.125C12.6753 7.125 11.9394 6.74466 11.4581 6.14981L7.04521 8.35515C7.09732 8.56146 7.125 8.7775 7.125 9C7.125 9.22261 7.09729 9.43876 7.04513 9.64517L11.4582 11.8501C11.9394 11.2553 12.6753 10.875 13.5 10.875C14.9497 10.875 16.125 12.0503 16.125 13.5C16.125 14.9497 14.9497 16.125 13.5 16.125C12.0503 16.125 10.875 14.9497 10.875 13.5C10.875 13.2778 10.9026 13.0621 10.9546 12.8561L6.54272 10.6487C6.06151 11.2442 5.32522 11.625 4.5 11.625C3.05025 11.625 1.875 10.4497 1.875 9C1.875 7.55025 3.05025 6.375 4.5 6.375C5.32425 6.375 6.05977 6.75489 6.54102 7.34914L10.9545 5.14382C10.9026 4.93782 10.875 4.72213 10.875 4.5C10.875 3.05025 12.0503 1.875 13.5 1.875C14.9497 1.875 16.125 3.05025 16.125 4.5ZM13.5 6C14.3284 6 15 5.32843 15 4.5C15 3.67157 14.3284 3 13.5 3C12.6716 3 12 3.67157 12 4.5C12 5.32843 12.6716 6 13.5 6ZM4.5 10.5C5.32843 10.5 6 9.82843 6 9C6 8.17157 5.32843 7.5 4.5 7.5C3.67157 7.5 3 8.17157 3 9C3 9.82843 3.67157 10.5 4.5 10.5ZM15 13.5C15 14.3284 14.3284 15 13.5 15C12.6716 15 12 14.3284 12 13.5C12 12.6716 12.6716 12 13.5 12C14.3284 12 15 12.6716 15 13.5Z" fill="var(--foreground)"/>'
            + '</svg>';

        var noArticlesContent = publicoConfig.isPremium
            ? {
                title: "Boas histórias merecem ser partilhadas",
                desc: 'Já ofereceu todos os artigos disponíveis este mês. Não se preocupe, no <strong>próximo mês recebe mais 12</strong> para oferecer. Até lá, pode continuar a partilhar artigos exclusivos com outros assinantes.',
                actions: '<button button-share-offer class="offer-panel__btn">' + shareIconSVG + ' Partilhar</button>'
            }
            : {
                title: "Quer continuar a oferecer artigos?",
                desc: 'Já ofereceu todos os artigos disponíveis este mês. Não se preocupe, no <strong>próximo mês recebe mais 6</strong> para oferecer. Até lá, pode continuar a partilhar artigos exclusivos com outros assinantes.',
                actions: '<button button-share-offer class="offer-panel__btn">' + shareIconSVG + ' Partilhar</button>'
            };

        document.querySelectorAll("button.button--subscriptions.button--offer").forEach(function (shareButton) {
            shareButton.classList.remove("hidden");
        });

        fetch("/api/user/" + userOnPage.userGuid + "/share/left", {
            method: "POST",
            headers: { 'Content-Type': 'application/json' },
        }).then(function (result) {
            return result.json();
        }).then(function (data) {
            if (!data.status) return;

            userOnPage.userSharesLeft = data.result;
            var sharedCount = maxShares - data.result;

            var title = panel.querySelector(".offer-panel__title");
            var desc = panel.querySelector(".offer-panel__description");
            var actions = panel.querySelector(".offer-panel__actions");
            var info = panel.querySelector(".offer-panel__info");
            if (data.result < 1) {

                if (title) title.innerHTML = noArticlesContent.title;
                if (desc) desc.innerHTML = noArticlesContent.desc;
                if (actions) actions.innerHTML = noArticlesContent.actions;
                if (info) info.remove();
                var shareBtn = actions && actions.querySelector(".offer-panel__btn");
                if (shareBtn) {
                    shareBtn.addEventListener("click", function () {
                        dataLayer.push({
                            event: "offer_article_share",
                            action: "boas_historias_merecemser_partilhadas_botaopartilha"
                        });
                        if (navigator.share) {
                            navigator.share({
                                title: jsonld.headline || document.title,
                                url: window.location.href
                            });
                        }
                    });
                }

            } else {
                if (title) title.textContent = sharedCount > 0
                    ? "Ainda tem " + data.result + " artigos para oferecer"
                    : "Ainda tem " + maxShares + " artigos para oferecer";
                if (desc) {
                    desc.textContent = maxShares === 12
                        ? "Conhece uma pessoa que ia gostar de ler este artigo exclusivo? Tem 12 por mês para oferecer."
                        : "Conhece uma pessoa que ia gostar de ler este artigo exclusivo? Tem 6 por mês para oferecer.";
                }
            }
            var FORCE_INTRO = false;
            var isFirstVisit = !document.cookie.split(';').some(function (c) {
                return c.trim().startsWith('offer-intro-seen=');
            });
            var subscriptionStart = userOnPage.subscriptionStart;
            var days = subscriptionStart ? (new Date() - new Date(subscriptionStart)) / (1000 * 60 * 60 * 24) : 999;

            if ((isFirstVisit && days < 15) || FORCE_INTRO) {
                var originalTitle = panel.querySelector('.offer-panel__title').innerHTML;
                var originalDesc = panel.querySelector('.offer-panel__description').innerHTML;
                var originalActions = panel.querySelector('.offer-panel__actions').innerHTML;
                panel.classList.add('offer-panel-intro');

                panel.querySelector('.offer-panel__title').insertAdjacentHTML('beforebegin',
                    '<div class="image_wrapper_offer"><img src="https://www.publico.pt/site-2022/assets/img/fluxo-oferta-artigos/presente.png" alt="Cadeado" width="63" height="68"></div>'
                );
                panel.querySelector('.offer-panel__title').textContent = 'Sabia que pode oferecer artigos?';
                panel.querySelector('.offer-panel__description').textContent = 'Pode oferecer até ' + maxShares + ' artigos exclusivos por mês aos seus amigos e familiares, mesmo que não sejam assinantes.';
                panel.querySelector('.offer-panel__actions').innerHTML = '<button type="button" class="offer-intro__btn offer-panel__btn button--subscriptions">Experimentar agora</button>';


                document.getElementById('offer-close').addEventListener('click', function () {
                    document.cookie = "offer-intro-seen=1; max-age=" + (365 * 24 * 60 * 60) + "; path=/";
                }, { once: true });

                panel.querySelector('.offer-intro__btn').addEventListener('click', function () {
                    dataLayer.push({
                        event: "offer_article_share",
                        action: "botao_experimentar_agora"
                    });
                    closePanel();
                    panel.classList.remove('offer-panel-intro');
                    document.cookie = "offer-intro-seen=1; max-age=" + (365 * 24 * 60 * 60) + "; path=/";
                    var imgWrapper = panel.querySelector('.image_wrapper_offer');
                    if (imgWrapper) imgWrapper.remove();
                    panel.querySelector('.offer-panel__title').innerHTML = originalTitle;
                    panel.querySelector('.offer-panel__description').innerHTML = originalDesc;
                    panel.querySelector('.offer-panel__actions').innerHTML = originalActions;

                    var buttons = document.querySelectorAll('button.button--subscriptions.button--offer');
                    if (!buttons.length) return;
                    var closest = null, minDist = Infinity;
                    var centerY = window.innerHeight / 2;
                    buttons.forEach(function (b) {
                        var rect = b.getBoundingClientRect();
                        var dist = Math.abs(rect.top + rect.height / 2 - centerY);
                        if (dist < minDist) { minDist = dist; closest = b; }
                    });
                    if (!closest) return;

                    var existingPulse = closest.querySelector('.status-pulse');
                    if (existingPulse) existingPulse.remove();

                    var pulse = document.createElement('div');
                    pulse.className = 'status-pulse';
                    pulse.setAttribute('aria-hidden', 'true');
                    pulse.innerHTML = `<span class="pulse-ring"></span><svg class="dot" xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"><circle cx="12" cy="12" r="5.2" fill="#64676B"></circle></svg>`;

                    var pos = window.getComputedStyle(closest).position;
                    if (pos === 'static') closest.style.position = 'relative';

                    // closest.style.overflow = 'visible';

                    closest.appendChild(pulse);

                    closest.scrollIntoView({ behavior: 'smooth', block: 'center' });

                    setTimeout(function () { pulse.remove(); }, 900000);
                });
            }
        }).catch(function (err) {
            console.error("Erro ao obter artigos restantes:", err);
        });

        function positionPanel(shareButton) {
            var rect = shareButton.getBoundingClientRect();
            var left = rect.right - panel.offsetWidth;
            if (left < 16) left = 16;
            panel.style.position = 'fixed';
            panel.style.top = (rect.bottom + 22) + 'px';
            panel.style.left = left + 'px';
            panel.style.right = 'auto';
            panel.style.bottom = 'auto';
            panel.style.transform = 'none';
            panel.style.setProperty('--arrow-left', (rect.left + (rect.width / 2) - left) + 'px');

            var buttons = Array.from(document.querySelectorAll("button.button--subscriptions.button--offer"));
            var idx = buttons.indexOf(shareButton);
            var isSecondButton = (idx === 1);

            if (isSecondButton) {
                panel.classList.add('is-second-anchor');

            } else {
                panel.classList.remove('is-second-anchor');
            }

        }

        document.addEventListener('click', function (e) {
            var shareButton = e.target.closest("button.button--subscriptions.button--offer");

            if (shareButton) {
                e.preventDefault();
                var buttons = Array.from(document.querySelectorAll("button.button--subscriptions.button--offer"));
                var idx = buttons.indexOf(shareButton);
                dataLayer.push({
                    event: "offer_article_exclusive",
                    action: idx === 0 ? "oferecer_artigo_topo" : "oferecer_artigo_inferior"
                });

                panel.classList.contains('is-open') ? closePanel() : openPanel(shareButton);
                return;
            }

            if (panel.classList.contains('is-open') && !panel.contains(e.target)) {
                closePanel();
            }
        });

        var closeBtn = document.getElementById('offer-close');
        if (closeBtn) closeBtn.addEventListener('click', function (e) { e.preventDefault(); closePanel(); });
        if (overlay) overlay.addEventListener('click', closePanel);
        if (lock) lock.addEventListener('click', closePanel);

        var activeButton = null;

        function openPanel(shareButton) {
            activeButton = shareButton;

            panel.classList.add('is-open');
            if (overlay) overlay.classList.add('is-open');

            if (window.innerWidth >= 768) {
                if (lock) lock.classList.add('is-active');

                requestAnimationFrame(function () {
                    positionPanel(shareButton);

                    var margin = 16;
                    var r = panel.getBoundingClientRect();
                    var overflowBottom = r.bottom - (window.innerHeight - margin);
                    var overflowTop = margin - r.top;

                    if (overflowBottom > 0) {
                        window.scrollBy({ top: overflowBottom, left: 0, behavior: 'smooth' });
                    } else if (overflowTop > 0) {
                        window.scrollBy({ top: -overflowTop, left: 0, behavior: 'smooth' });
                    }

                    setTimeout(function () {
                        positionPanel(shareButton);
                        document.body.classList.add('no-scroll');
                    }, 250);
                });
            } else {
                document.body.classList.add('no-scroll');
                panel.style.cssText = '';
            }
        }

        function closePanel() {
            activeButton = null;
            panel.classList.remove('is-open');
            panel.style.cssText = '';
            if (overlay) overlay.classList.remove('is-open');
            if (lock) lock.classList.remove('is-active');
            document.body.classList.remove('no-scroll');
        }

        window.addEventListener('resize', function () {
            if (!panel.classList.contains('is-open') || !activeButton) return;
            if (window.innerWidth >= 768) {
                requestAnimationFrame(function () { positionPanel(activeButton); });
                if (lock) lock.classList.add('is-active');
            } else {
                panel.style.cssText = '';
                if (lock) lock.classList.remove('is-active');
                if (overlay) overlay.classList.add('is-open');
            }
        });
    });
}

